"""Open-category screening orchestration using the shared embedding/Qwen broker."""
import copy
import json
import math
import time

import numpy as np

from . import normality as n
from .store import ReindexRequired


def snapshot_policy(service, profile_id):
    profile = n.profile(service.store, profile_id)
    bank = n.bank(service.store, profile_id)
    config = json.loads(json.dumps(service.config.json()))
    if bank and bank["config"] != config:
        raise ReindexRequired("Reference configuration mismatch")
    # Locks are generated by the validation harness, never inferred from test outcomes.
    path = service.store.root / "normality-locks" / f"{profile_id}.json"
    thresholds = copy.deepcopy(n.DEFAULT_THRESHOLDS)
    status = "experimental_unvalidated"
    if path.exists():
        lock = json.loads(path.read_text(encoding="utf-8"))
        if (lock.get("config") != config or lock.get("reference_version") != profile["current_version"]
                or lock.get("policy") != n.POLICY or lock.get("prompt_hash") != n.digest(n.PROMPTS)
                or lock.get("split") != "validation" or not lock.get("manifest_hash")):
            raise ReindexRequired("Normality validation lock mismatch")
        thresholds = lock["thresholds"]
        if set(thresholds) != set(n.DEFAULT_THRESHOLDS):
            raise ValueError("Missing channel thresholds")
        for limits in thresholds.values():
            if set(limits) != {"novelty", "margin", "similarity"} or any(type(v) not in (int, float) or not math.isfinite(v) for v in limits.values()):
                raise ValueError("Invalid validation thresholds")
        status = "validation_locked_experimental"
    return {"profile_id": profile_id, "reference_version": profile["current_version"], "config": config,
            "context": profile["context"], "thresholds": thresholds, "threshold_status": status,
            "policy": n.POLICY, "prompts": copy.deepcopy(n.PROMPTS), "prompt_hash": n.digest(n.PROMPTS)}


def reference_frames(service, references):
    frames = []
    for ref in references[:2]:
        video = service.store.get("videos", ref["video_id"])
        service.validate_source(video)
        rows = service.store.windows(service.namespace(video))
        row = next((w for w in rows if w["id"] == ref["window_id"]), None)
        if row and row["frame_paths"]:
            frames.append({"path": row["frame_paths"][len(row["frame_paths"])//2], "video_id": ref["video_id"],
                           "timestamp": row["timestamps"][len(row["frame_paths"])//2]})
    return frames


def screen_open(service, job_id):
    job = service.store.get("jobs", job_id)
    policy = job["open_policy"]
    if policy["config"] != json.loads(json.dumps(service.config.json())):
        raise ReindexRequired("Resumed job configuration changed")
    bank = n.bank(service.store, policy["profile_id"], policy["reference_version"]) if policy["reference_version"] else None
    if bank:
        for ref in bank["references"]:
            video_ref = service.store.get("videos", ref["video_id"])
            service.validate_source(video_ref)
            if ref["fingerprint"] != video_ref["fingerprint"]:
                raise ReindexRequired("Reference source changed")
    video = service.store.get("videos", job["video_id"])
    service.validate_source(video)
    namespace = service.namespace(video)
    timeline = service.store.require(video["id"], namespace)
    service.update(job_id, phase="screen", namespace=namespace, screening_policy=n.POLICY,
                   reference_status="ready" if bank else "reference_missing", event_types=["open_anomaly"])
    with service.gpu_lock:
        prompts = tuple(np.stack([service.query_vector(text + " Scene context: " + policy["context"])[0]
                                  for text in policy["prompts"][role]]) for role in ("suspicious", "normal"))
    channels = service.store.embeddings(namespace, service.config.dimension)
    evidence = n.score_channels(channels, bank, prompts, policy["thresholds"], service.config.dimension)
    units = n.segments(timeline, evidence)
    pending = []
    for item in units:
        service.check_cancel(job_id)
        key = n.digest([namespace, job_id, item["t_start"], item["t_end"]])[:24]
        try:
            old = service.store.get("events", key)
            if old.get("verification_complete"):
                continue
            event = old
        except KeyError:
            references = {}
            for window in item["evidence"].values():
                for entries in window.values():
                    for score in entries:
                        for ref in score["references"]:
                            references.setdefault(ref["key"], ref)
            event = {**item, "id": key, "video_id": video["id"], "namespace": namespace,
                     "label": "ความผิดปกติทั่วไป", "model_status": "pending", "review": "pending",
                     "assessment": "uncertain", "reference_status": "ready" if bank else "reference_missing",
                     "references": list(references.values())[:2], "open_policy": policy,
                     "screening_job_id": job_id, "screening_policy": n.POLICY, "audio_verified": False,
                     "audio_status": "available" if video["has_audio"] else "no_audio",
                     "threshold_status": policy["threshold_status"], "caption_full": "",
                     "refinement_status": "bounded_window", "context_t_start": max(0, item["t_start"]-5),
                     "context_t_end": min(video["duration"], item["t_end"]+5),
                     "preview_frame_path": f"/api/v1/events/videos/{video['id']}/frames/{item['window_ids'][0]}"}
            service.store.save_event(event)
        pending.append(event)
    calls = job.get("qwen_calls", 0)
    unknown_calls = job.get("qwen_calls_unknown", 0)
    measured = job.get("telemetry", {})
    baseline = job.get("qwen_baseline_calls", len(timeline))
    service.update(job_id, phase="verify", total=len(units), completed=len(units)-len(pending),
                   qwen_calls=calls, qwen_baseline_calls=baseline, merged_events=len(units),
                   candidate_windows=sum(any(s["selected"] for values in e.values() for s in values) for e in evidence.values()),
                   screening_scores=evidence)
    for offset in range(0, len(pending), 8):
        service.check_cancel(job_id)
        batch = pending[offset:offset+8]
        payload = []
        for event in batch:
            try:
                frames = n.sample_frames(video["path"], event["t_start"], event["t_end"], video["duration"],
                                         service.store.root / "open-verification" / event["id"])
                event["verification_frames"] = frames
                service.store.save_event(event)
                payload.append(verify_payload(service, event, frames, policy))
            except Exception as exc:
                event["verification"] = {"status": "unverified", "error": str(exc)}
                event["model_status"] = "unverified"
                service.store.save_event(event)
        results = verify(service, payload)
        measured = merge_telemetry(measured, service.client.last_telemetry)
        for event in batch:
            if event["id"] not in results:
                continue
            result = results[event["id"]]; calls += result.get("calls", 0)
            unknown_calls += int(result.get("calls_unknown", False))
            attempts = [result]
            if (result.get("verdict") or {}).get("assessment") == "uncertain":
                # Rank subwindows by gate excess, no test labels or future information.
                starts = sorted({max(event["t_start"], min(w["t_start"], event["t_end"]-3))
                                 for w in timeline if w["id"] in event["window_ids"]},
                                key=lambda t: (-retry_priority(t, event, timeline), t))[:2]
                for retry, start in enumerate(starts):
                    service.check_cancel(job_id)
                    try:
                        frames = n.sample_frames(video["path"], start, min(start+3, event["t_end"]), video["duration"],
                                                 service.store.root / "open-verification" / event["id"] / f"retry-{retry}", False)
                        answer = verify(service, [verify_payload(service, event, frames, policy)])[event["id"]]
                        measured = merge_telemetry(measured, service.client.last_telemetry)
                        answer["frames"] = frames
                        attempts.append(answer); calls += answer.get("calls", 0)
                        unknown_calls += int(answer.get("calls_unknown", False))
                        if (answer.get("verdict") or {}).get("assessment") == "suspicious":
                            result = answer
                            break
                    except Exception as exc:
                        attempts.append({"status": "unverified", "error": str(exc)})
                # Normal subclips cannot establish that the whole uncertain unit is normal.
            event.update(model_status=result.get("status", "unverified"), verification=result,
                         assessment=(result.get("verdict") or {}).get("assessment", "uncertain"),
                         contextual_attempts=attempts, verification_complete=result.get("status") == "verified")
            if result.get("frames"):
                event["verification_frames"] = result["frames"]
            event["caption_full"] = json.dumps(result.get("verdict") or {}, ensure_ascii=False, indent=2)
            service.store.save_event(event)
        service.update(job_id, completed=min(len(units), len(units)-len(pending)+offset+len(batch)),
                       qwen_calls=calls, qwen_calls_unknown=unknown_calls, telemetry=measured)
    service.client.last_telemetry = measured
    service.validate_source(video)


def verify_payload(service, event, frames, policy):
    return {"id": event["id"], "kind": "open_anomaly", "verification_mode": n.POLICY,
            "generate_caption": False, "scene_context": policy["context"],
            "timestamps": [f["timestamp"] for f in frames], "frame_paths": [f["path"] for f in frames],
            "reference_frames": reference_frames(service, event["references"])}


def verify(service, payload):
    if not payload:
        return {}
    try:
        with service.gpu_lock:
            response = service.client.post("/verify-batch", {"events": payload}, timeout=len(payload)*480+30)
        service.client.last_telemetry = response.get("telemetry", {})
        results = {r["id"]: r for r in response["results"]}
        return {p["id"]: results.get(p["id"], {"status": "unverified", "error": "Missing worker result"}) for p in payload}
    except Exception as exc:
        service.client.last_telemetry = {}
        return {p["id"]: {"status": "unverified", "error": str(exc), "calls_unknown": True} for p in payload}


def merge_telemetry(previous, current):
    result = {**previous, **current}
    before, after = previous.get("qwen_resources", {}), current.get("qwen_resources", {})
    if after:
        resource = {**before, **after}
        for field in ("sampled_whole_gpu_peak_bytes", "qwen_process_tree_peak_rss_bytes"):
            resource[field] = max(before.get(field) or 0, after.get(field) or 0) or None
        resource["samples"] = before.get("samples", 0)+after.get("samples", 0)
        result["qwen_resources"] = resource
        result["verification_batch_seconds"] = previous.get("verification_batch_seconds", 0)+current.get("verification_batch_seconds", 0)
    return result


def retry_priority(start, event, timeline):
    values = []
    for w in timeline:
        if w["id"] not in event["window_ids"] or w["t_start"] >= start+3 or w["t_end"] <= start:
            continue
        for modality, scores in event["evidence"].get(str(w["id"]), {}).items():
            limits = event["open_policy"]["thresholds"][modality]
            for score in scores:
                values.append(max((score["novelty"] or 0)-limits["novelty"], score["margin"]-limits["margin"]))
    return max(values, default=0.)
